CREATE FUNCTION pg_temp.hw_resolve_41(p_key TEXT, p_data JSONB) RETURNS VOID LANGUAGE plpgsql AS $heroeswatch_41$
DECLARE
  incoming "heroes_watch"."TownScreen"%ROWTYPE;
  resolved_id TEXT;
  matches BIGINT;
BEGIN
  incoming := jsonb_populate_record(NULL::"heroes_watch"."TownScreen", p_data);
  SELECT count(*), min(target."TownScreen_id"::TEXT) INTO matches, resolved_id
  FROM "heroes_watch"."TownScreen" AS target
  WHERE target."Game_id" IS NOT DISTINCT FROM incoming."Game_id"
      AND target."Code" IS NOT DISTINCT FROM incoming."Code";
  IF matches > 1 THEN
    RAISE EXCEPTION 'Ambiguous existing identity: %/%. Review duplicate business keys or conflicting junction cid.', E'TownScreen', p_key;
  END IF;
  IF matches = 0 THEN
    resolved_id := nextval(pg_get_serial_sequence(E'"heroes_watch"."TownScreen"', E'TownScreen_id'))::TEXT;
    IF EXISTS (SELECT 1 FROM "heroes_watch"."TownScreen" WHERE "TownScreen_id" = resolved_id::BIGINT) THEN
      RAISE EXCEPTION 'Identity sequence behind existing IDs: %/%. Review sequence state before retrying.', E'TownScreen', p_key;
    END IF;
  END IF;
  INSERT INTO pg_temp.heroeswatch_import_keys (table_name, import_key, row_id)
  VALUES (E'TownScreen', p_key, resolved_id);
END
$heroeswatch_41$;

